// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        amount = bound(amount, 1, 100 ether);
        vm.assume(target != address(0) && target != address(c) && target != address(this));
        Acceptor acceptor = new Acceptor();
        address payable t = payable(address(acceptor));
        vm.deal(address(c), 100 ether);
        uint256 beforeBal = t.balance;
        c.sendMoney(t, amount);
        uint256 afterBal = t.balance;
        assertTrue(afterBal == beforeBal + amount);
    }
}

contract Acceptor {
    receive() external payable {}
}
